/** 
 * Returns a builder that creates immutable sorted sets whose elements are ordered by the reverse of their natural ordering. <p>Note: the type parameter  {@code E} extends {@code Comparable<E>} ratherthan  {@code Comparable<? super E>} as a workaround for javac <ahref="http://bugs.sun.com/bugdatabase/view_bug.do?bug_id=6468354">bug 6468354</a>.
 */
public static <E extends Comparable<E>>Builder<E> reverseOrder(){
  return new Builder<E>(Ordering.natural().reverse());
}
